const $=s=>document.querySelector(s),main=$('#mainpage'),detail=$('#unitpage'),dialog=$('#modal'),body=$('#modalbody');
const fmt=n=>n==null?'تُؤكَّد مع إدارة التأجير':Number(n).toLocaleString('ar-EG',{maximumFractionDigits:2})+' م²';
const byId=new Map(UNITS.map(u=>[u.id,u])),states=new Map();let fl='g',shownUnit=null,zoom=false,lastFocus=null;
const codeText=u=>u.pending?fmt(u.area):u.id;
function el(tag,cl,text){const n=document.createElement(tag);if(cl)n.className=cl;if(text!==undefined)n.textContent=text;return n}
function btn(label,callback,cl='secondary'){let b=el('button',cl,label);b.type='button';b.onclick=callback;return b}
function currentRoute(){
  if(location.hash){try{return decodeURIComponent(location.hash.slice(1))}catch{return ''}}
  const p=new URLSearchParams(location.search);
  if(p.has('unit'))return 'unit/'+normalized(p.get('unit'));
  if(p.has('floor'))return 'plan/'+p.get('floor').toLowerCase();
  return '';
}
function routeURL(route,view,shot,scene){
  const url=new URL(location.href);
  for(const k of ['unit','floor','view','shot','scene','doc','page'])url.searchParams.delete(k);
  url.hash='';
  if(route.startsWith('unit/')){url.searchParams.set('unit',route.slice(5));if(view)url.searchParams.set('view',view);if(shot)url.searchParams.set('shot',shot);if(scene)url.searchParams.set('scene',scene)}
  else if(route.startsWith('plan/'))url.searchParams.set('floor',route.slice(5));
  else if(route)url.hash=route;
  return url.pathname+url.search+url.hash;
}
function navigateSite(key,view,shot,scene){
  const dest=routeURL(key,view,shot,scene);
  if(location.pathname+location.search+location.hash!==dest)history.pushState(null,'',dest);
  dispatchRoute(true);
}
function href(txt,url,cl='secondary'){let a=el('a',cl,txt);if(url.startsWith('#')){a.dataset.route=url.slice(1);a.href=routeURL(a.dataset.route)}else a.href=url;return a}
function img(url,alt,cl=''){let i=el('img',cl);i.src=url;i.alt=alt;return i}
function opt(s,t,v){let o=el('option','',t);o.value=v;s.append(o)}
function stat(grid,title,value){let d=el('div');d.append(el('small','',title),el('b','',value));grid.append(d)}
function clearFields(){for(let id of ['search','min','max','cat'])$('#'+id).value=''}
function floorState(){return {q:$('#search').value,cat:$('#cat').value,min:$('#min').value,max:$('#max').value,left:$('#mapscroll').scrollLeft,top:$('#mapscroll').scrollTop,zoom}}
function saveFloor(){states.set(fl,floorState())}
function setZoom(on){zoom=on;$('#mapscroll').classList.toggle('zoom',on);$('#zoom').setAttribute('aria-pressed',String(on));$('#zoom').textContent=on?'تصغير المخطط −':'تكبير المخطط ＋'}
function normalized(s){return (s||'').toUpperCase().replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/\s/g,'')}
function matches(u,q,cat,lo,hi){return (!q||u.id.includes(q)||(u.pending&&String(u.area).includes(q.replace('٫','.'))))&&(!cat||u.cat===cat)&&(!lo||(u.area!=null&&u.area>=+lo))&&(!hi||(u.area!=null&&u.area<=+hi))}
function filter(){let q=normalized($('#search').value),cat=$('#cat').value,lo=$('#min').value,hi=$('#max').value;
 let active=UNITS.filter(u=>u.f===fl&&matches(u,q,cat,lo,hi));const ids=new Set(active.map(u=>u.id));for(const link of $('#mapcanvas').querySelectorAll('[data-id]')){const inactive=!ids.has(link.dataset.id);link.toggleAttribute('inert',inactive);link.classList.toggle('dim',inactive);if(link.classList.contains('pin'))link.tabIndex=inactive?-1:0;}
 const rs=$('#rs');rs.replaceChildren();$('#rc').textContent=active.length.toLocaleString('ar-EG')+' موقع على مخطط '+FLOORS[fl];for(const u of active){let a=href('','#unit/'+u.id,'rowunit');a.append(el('b','',codeText(u)));let span=el('span','',u.cat);span.append(el('small','',fmt(u.area)+(u.held?' · محجوز على اللوحة':'')));a.append(span);rs.append(a)}
 if(!active.length)rs.append(el('p','caption','لا توجد نتائج مطابقة في هذا الدور. جرّب دورًا آخر أو امسح الاختيارات.'))}
function drawFloor(f,restore){fl=f;document.getElementById('basement-program').hidden=f!=='b1';$('#floortitle').textContent=FLOORS[f];for(const a of $('#tabs').children)a.setAttribute('aria-current',String(a.dataset.route==='plan/'+f));const sel=UNITS.filter(u=>u.f===f),c=$('#mapcanvas');c.replaceChildren(img(MAPS[f],'لوحة التأجير الملونة '+FLOORS[f]));
 const ns='http://www.w3.org/2000/svg';
 const zones=document.createElementNS(ns,'svg');zones.setAttribute('viewBox','0 0 1108 1100');zones.setAttribute('preserveAspectRatio','none');zones.setAttribute('aria-hidden','true');zones.classList.add('unit-hit-areas');
 for(const u of sel){
   const polygon=UNIT_DRAWINGS[u.id]?.polygon;if(!polygon?.length)continue;
   const link=document.createElementNS(ns,'a');link.setAttribute('href',routeURL('unit/'+u.id));link.dataset.route='unit/'+u.id;link.dataset.id=u.id;link.setAttribute('tabindex','-1');
   const shape=document.createElementNS(ns,'polygon');shape.setAttribute('points',polygon.map(pt=>pt.join(',')).join(' '));link.append(shape);zones.append(link);
 }
 c.append(zones);
 for(const u of sel){let a=href(u.pending?String(u.area):u.id,'#unit/'+u.id,'pin'+(u.held?' res':''));a.dataset.id=u.id;a.style.left=(u.x/1108*100)+'%';a.style.top=(u.y/1100*100)+'%';a.title=codeText(u)+' · '+u.title+' · '+fmt(u.area);a.setAttribute('aria-label','صفحة '+a.title);c.append(a)}
 let s=$('#cat');s.replaceChildren();opt(s,'كل الأنشطة','');for(let cat of new Set(sel.map(u=>u.cat)))opt(s,cat,cat);clearFields();
 const st=restore&&states.get(f);if(st){$('#search').value=st.q;s.value=st.cat;$('#min').value=st.min;$('#max').value=st.max}setZoom(st?st.zoom:false);$('#mapscroll').scrollLeft=st?st.left:0;$('#mapscroll').scrollTop=st?st.top:0;filter();$('#floorfoot').textContent=f==='f2'?'تُعرض أربعة مواقع في هذا الدور بمساحاتها. تُؤكّد إدارة التأجير أرقامها عند الاستفسار.':'المساحات الإجمالية وفق لوحة التأجير.'}
for(const [id,name] of Object.entries(FLOORS))$('#tabs').append(href(name,'#plan/'+id,''));
for(const id of ['search','cat','min','max'])$('#'+id).addEventListener(id==='cat'?'change':'input',filter);
$('#reset').onclick=()=>{clearFields();filter()};$('#zoom').onclick=()=>setZoom(!zoom);
