 if(hash.startsWith('unit/')){let u=byId.get(hash.slice(5));if(u){if(!shownUnit)saveFloor();if(!shownUnit||shownUnit.id!==u.id){for(const v of main.querySelectorAll('video'))if(!v.paused)v.pause()}unitView(u);return}}
 closeUnitScene();let returning=shownUnit;shownUnit=null;main.hidden=false;detail.hidden=true;document.title='هابينس بلازا | دليل الوحدات التجارية والتأجير';
 if(hash.startsWith('plan/')){let f=hash.slice(5);if(!FLOORS[f])f='g';if(!returning&&f!==fl)saveFloor();drawFloor(f,true);goSection('atlas');if(returning&&returning.f===f){const mark=$('#mapcanvas').querySelector('.pin[data-id="'+returning.id+'"]');if(mark)mark.focus({preventScroll:true})}return}
 if(hash==='location-film')document.getElementById('location-film').open=true;
