function picture(k){let title=k==='hyper'?'لوحة تصميم هايبر ماركت الحبيب':'رسم واجهات المحلات واللافتات';openBox(title);body.append(img(IMAGES[k],title,'lightbox'))}
const BRAND_LOGOS={"hotel": ["assets/logo-hotel.png", "Plaza Hotel"], "bok": ["assets/logo-bok.png", "Bokharest Black"], "joypark": ["assets/logo-joypark.png", "Joy Park"], "guru": ["assets/logo-guru.png", "Guru Fit"], "aura": ["assets/logo-aura.png", "AURA Beauty Lounge & Spa"], "pharmacy": ["assets/logo-pharmacy.png", "Happiness Pharmacy"]};function album(k){let a=ALBUMS[k],i=0;openBox(a.title);if(BRAND_LOGOS[k]){const [src,name]=BRAND_LOGOS[k];const mark=document.createElement('img');mark.className='brandmark';mark.src=src;mark.alt=name;document.getElementById('dialogtitle').replaceChildren(mark)}let photo=img('',a.title,'gal'),cap=el('p','caption'),pager=el('div','pager'),count=el('span'),next=btn('التالي',()=>pick(i+1),'tool'),prev=btn('السابق',()=>pick(i-1),'tool');function pick(n){i=n;photo.src=a.photos[i].src;photo.alt=a.photos[i].caption;cap.textContent=a.photos[i].caption;prev.disabled=i===0;next.disabled=i===a.photos.length-1;count.textContent=(i+1).toLocaleString('ar-EG')+' / '+a.photos.length.toLocaleString('ar-EG')}pager.append(prev,count,next);body.append(el('p','',a.desc),photo,cap,pager);let actions=el('div','actions');if(VIDEO[k])actions.append(btn('شاهد فيديو النشاط',()=>video(k,a.title),'action'));if(REPORTS[k]){let dl=href('دليل النشاط المصوّر',REPORTS[k]);dl.download=k+'.pdf';actions.append(dl)}let l=href(k==='bok'||k==='joy'?'قائمة الطعام':'الموقع الرسمي للنشاط',a.url);actions.append(l);body.append(actions);pick(0)}
function booking(u){openBox('استفسار عن وحدة تجارية');let form=el('form','booking');for(const [key,lab,val] of [['brand','اسم العلامة التجارية',''],['activity','النشاط',u?.cat||''],['code','الوحدة أو الموقع',u?codeText(u)+' · '+FLOORS[u.f]:''],['area','المساحة المطلوبة (م²)',u?.area||'']]){let l=el('label','',lab),inp=el('input');inp.name=key;inp.value=val;if(key==='area'){inp.type='number';inp.min='0.01';inp.step='any'}inp.required=key==='brand'||key==='activity';l.append(inp);form.append(l)}
 let send=el('button','action','متابعة الطلب في واتساب');send.type='submit';form.append(send);form.onsubmit=e=>{e.preventDefault();let data=new FormData(form),parts=['طلب معاينة – هابينس بلازا'];for(const [k,t] of [['brand','اسم العلامة التجارية'],['activity','النشاط'],['code','الوحدة'],['area','المساحة المطلوبة بالمتر المربع']])if(data.get(k))parts.push(t+' — '+data.get(k));location.assign('https://wa.me/201227777104?text='+encodeURIComponent(parts.join('\n')))};body.append(form)}
function connectTabs(list, vertical) {
  const tabs = Array.from(list.querySelectorAll('[role="tab"]'));
  function choose(index, focus) {
    tabs.forEach((tab, i) => {
      const selected = i === index;
      tab.setAttribute('aria-selected', String(selected));
      tab.tabIndex = selected ? 0 : -1;
      document.getElementById(tab.getAttribute('aria-controls')).hidden = !selected;
    });
    if (focus) tabs[index].focus();
  }
  for (const [index, tab] of tabs.entries()) {
    tab.addEventListener('click', () => choose(index, false));
    tab.addEventListener('keydown', event => {
      let next;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = tabs.length - 1;
      if (event.key === 'ArrowLeft' || (vertical && event.key === 'ArrowDown')) next = (index+1)%tabs.length;
      if (event.key === 'ArrowRight' || (vertical && event.key === 'ArrowUp')) next = (index-1+tabs.length)%tabs.length;
      if (next !== undefined) {event.preventDefault(); choose(next, true);}
    });
  }
}
connectTabs(document.querySelector('.scene-strip'), false);
connectTabs(document.querySelector('.venue-index'), true);
let comparisonIds = [];
const comparisonKey = 'happiness-plaza-unit-comparison';
try {
  const saved = JSON.parse(localStorage.getItem(comparisonKey) || '[]');
  if (Array.isArray(saved)) comparisonIds = [...new Set(saved.filter(id=>byId.has(id)))].slice(0,3);
} catch {}
function updateComparison() {
  document.querySelectorAll('.compare-count').forEach(el => el.textContent = comparisonIds.length.toLocaleString('ar-EG'));
  try {localStorage.setItem(comparisonKey, JSON.stringify(comparisonIds));} catch {}
  document.querySelectorAll('[data-compare-unit]').forEach(button=>{
    const on=comparisonIds.includes(button.dataset.compareUnit);
    button.disabled = !on && comparisonIds.length >= 3;
    button.setAttribute('aria-pressed',String(on));
    button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  });
}
function makeCompareButton(u) {
  const button = btn('', ()=>{
    const selected=comparisonIds.includes(u.id);
    if (selected) comparisonIds=comparisonIds.filter(id=>id!==u.id);
    else if (comparisonIds.length<3) comparisonIds.push(u.id);
    updateComparison();
  },'secondary');
  button.dataset.compareUnit=u.id;
  const on=comparisonIds.includes(u.id);
  button.disabled=!on && comparisonIds.length>=3;
  button.setAttribute('aria-pressed',String(on));
  button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  return button;
}
function openComparison(){
  if(dialog.open && document.getElementById('dialogtitle').textContent==='مقارنة الوحدات') body.replaceChildren();
  else openBox('مقارنة الوحدات');
  if(!comparisonIds.length) {
    body.append(el('p','','افتح رقم محل من المخطط واختر «أضف للمقارنة». يمكنك عرض بيانات ثلاث وحدات جنبًا إلى جنب.'));
    const backToMap=href('افتح المخطط','#plan/'+(shownUnit?.f||fl));
    backToMap.addEventListener('click',()=>dialog.close());
    body.append(backToMap);return;
  }
  const items=comparisonIds.map(id=>byId.get(id));
  const scroller=el('div','comparison-scroll'), table=el('table','comparison');
  table.setAttribute('aria-label','بيانات الوحدات المختارة');
  const head=table.createTHead().insertRow();
  head.append(el('th','','الوحدة'));
  for(const u of items){const th=el('th');th.scope='col';const link=href(u.pending?u.title:u.id,'#unit/'+u.id,'under');link.addEventListener('click',()=>dialog.close());th.append(link);head.append(th);}
  const rows=[['الدور',u=>FLOORS[u.f]],['النشاط',u=>u.cat],['مساحة التأجير',u=>fmt(u.area)],['المساحة الإضافية',u=>u.extra?u.elab+' · '+fmt(u.extra):'غير مبيّنة'],['التوافر',u=>u.status]];
  const tb=table.createTBody();
  for(const [title,get] of rows){const row=tb.insertRow(),th=el('th','',title);th.scope='row';row.append(th);for(const u of items)row.append(el('td','',get(u)));}
  const row=tb.insertRow();row.append(el('th','','تعديل الاختيارات'));
  for(const u of items){
    const cell=el('td'), remove=btn('إزالة',()=>{comparisonIds=comparisonIds.filter(id=>id!==u.id);updateComparison();openComparison();$('#close').focus();},'tool');
    remove.setAttribute('aria-label','إزالة '+u.id+' من المقارنة');cell.append(remove);row.append(cell);
  }
  scroller.append(table);body.append(scroller);
  const back=href('اختر وحدة أخرى من المخطط','#plan/'+(shownUnit?.f||fl));
  back.addEventListener('click',()=>dialog.close());
  body.append(back);
}
document.querySelector('.compare-open').addEventListener('click',openComparison);
updateComparison();
const chapterStops=[["home", "فيديو الموقع ونبذة عن المشروع"], ["stages", "مراحل تنفيذ المشروع"], ["phase", "المرحلة الأولى · الفندق والترفيه"], ["plaza", "بلازا المشروع"], ["lake", "البحيرة وجزيرة بوخارست"], ["rooms", "الفندق وغرفه"], ["owner", "شركة الحبيب للتنمية والاستثمار"], ["plan/g", "المرحلة الثانية · المحلات التجارية"], ["hyper", "المرحلة الثالثة · هايبر ماركت الحبيب"], ["market", "سوق قنا"], ["contact", "حجز معاينة"]];
let activeChapter=-1;
const presentationBar=document.querySelector('#presentbar');
function closePresentation(){
  activeChapter=-1; presentationBar.hidden=true;
  document.body.classList.remove('meeting-on');document.querySelector('#meeting-start').setAttribute('aria-pressed','false');
}
function showChapter(index){
  activeChapter=index; presentationBar.hidden=false;
  document.body.classList.add('meeting-on'); document.querySelector('#meeting-start').setAttribute('aria-pressed','true');
  document.querySelector('#pres-title').textContent=(index+1).toLocaleString('ar-EG')+' / '+chapterStops.length.toLocaleString('ar-EG')+' · '+chapterStops[index][1];
  document.querySelector('#pres-prev').disabled=index===0;
  document.querySelector('#pres-next').disabled=index===chapterStops.length-1;
  const dest=chapterStops[index][0];
  for(const player of document.querySelectorAll("video")) if(!player.paused) player.pause();
  navigateSite(dest);
}
document.querySelector('#meeting-start').addEventListener('click',()=>{
  if(activeChapter!==-1){closePresentation();return;}
  const position=chapterStops.findIndex(([hash])=>hash===currentRoute());
  showChapter(Math.max(0,position));
});
document.querySelector('#pres-exit').addEventListener('click',()=>{closePresentation();document.querySelector('#meeting-start').focus({preventScroll:true});});
document.querySelector('#pres-prev').addEventListener('click',()=>{if(activeChapter>0)showChapter(activeChapter-1);});
document.querySelector('#pres-next').addEventListener('click',()=>{if(activeChapter<chapterStops.length-1)showChapter(activeChapter+1);});

document.addEventListener('keydown',event=>{
  if(event.key==='Escape' && document.getElementById('links').classList.contains('open')){
    document.getElementById('links').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');document.getElementById('menu').focus();return;
  }
  if(activeChapter<0||dialog.open||event.defaultPrevented||event.target.closest('input,textarea,select,video,[role="tablist"]'))return;
  if(event.key==='Escape'){closePresentation();return;}
  if(event.key==='ArrowLeft'&&activeChapter<chapterStops.length-1){event.preventDefault();showChapter(activeChapter+1);}
  if(event.key==='ArrowRight'&&activeChapter>0){event.preventDefault();showChapter(activeChapter-1);}
});

document.addEventListener('click',e=>{let t=e.target.closest('[data-action]')?.dataset.action;if(t==='film')video('film','فيلم هابينس بلازا');else if(t==='onsite')video('onsite','مدخل هابينس بلازا');else if(t==='booking')booking(shownUnit);else if(t==='hyper'||t==='elevation')picture(t);else if(t?.startsWith('venue-'))album(t.slice(6));
 if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.altKey||e.shiftKey)return;
 const a=e.target.closest('a');if(!a)return;
 if(a.hasAttribute('data-presentation-start')){e.preventDefault();showChapter(0);return}
 if(a.hasAttribute('inert')){e.preventDefault();return}
 const dest=a.dataset.route;
 if(dest){
   e.preventDefault();
   navigateSite(dest,a.dataset.unitView,a.dataset.shot,a.dataset.scene);
   if(a.hasAttribute('data-play-film')){
     const player=document.getElementById(dest)?.querySelector('video');
     if(player){player.focus({preventScroll:true});player.play().catch(()=>{})}
   }
 }
});
$('#menu').onclick=()=>{let on=$('#links').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(on))};
let lastRouteURL, lastBaseURL;
function dispatchRoute(force=false){
 if(!force&&lastRouteURL===location.href)return;
 lastRouteURL=location.href;
 const base=new URL(location.href);
 base.searchParams.delete('doc');
 base.searchParams.delete('page');
 if(force||lastBaseURL!==base.href){
   lastBaseURL=base.href;
   if(activeChapter!==-1&&currentRoute()!==chapterStops[activeChapter][0])closePresentation();
   route();
 }
 syncDocument();
}
for(const name of ['popstate','hashchange'])window.addEventListener(name,()=>dispatchRoute());
window.addEventListener('DOMContentLoaded',()=>{drawFloor('g',false);dispatchRoute(true)},{once:true});

document.addEventListener('play',event=>{if(event.target.tagName==='VIDEO'){document.querySelectorAll('video').forEach(video=>{if(video!==event.target) video.pause()})}},true);
